import androidx.room.Dao
import androidx.room.Query

data class Task(val id: Int = 0, val title: String, val done: Boolean = false)

@Dao
interface TaskDao {
    @Query("SELECT * FROM tasks WHERE done = :isDone ORDER BY id")
    suspend fun byDone(done: Boolean): List<Task>
}

jvm.main:
fun main() = kotlinx.coroutines.runBlocking {
    val all = listOf(Task(1, "хлеб", true), Task(2, "сыр", false))
    val dao = object : TaskDao {
        override suspend fun byDone(done: Boolean): List<Task> = all.filter { it.done == done }
    }
    println(dao.byDone(false))
}

